<?php
session_start();require_once 'database.php';if(!isset($_SESSION['loggedinEmail'])){header('Location:login.php');exit;}$userId=(int)$_SESSION['userId'];$account=$conn->query("SELECT full_name,email FROM users WHERE id=$userId")->fetch_assoc();$savedOnly=isset($_GET['saved'])&&$_GET['saved']==='1';$chosen=(int)($_GET['job']??0);$sql='SELECT jobs.id,jobs.title,jobs.company,jobs.location,jobs.job_type,jobs.description,jobs.created_at,saved_jobs.id saved_id FROM jobs LEFT JOIN saved_jobs ON jobs.id=saved_jobs.job_id AND saved_jobs.user_id=? '.($savedOnly?'WHERE saved_jobs.id IS NOT NULL ':'').'ORDER BY jobs.created_at DESC';$q=$conn->prepare($sql);$q->bind_param('i',$userId);$q->execute();$result=$q->get_result();$jobs=[];while($j=$result->fetch_assoc())$jobs[]=$j;$first=$jobs[0]??null;foreach($jobs as $j)if($j['id']===$chosen)$first=$j;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $savedOnly?'Saved jobs':'Find jobs';?> | VUKA</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--o:#ff6b00;--b:#146cff}body{font-family:Inter,sans-serif;background:#f5f5f5;color:#171615}.page{max-width:1440px;padding-left:42px!important;padding-right:42px!important}.top,.filters{background:#fff;border-bottom:1px solid #ddd}.brand{font-size:1.85rem;font-weight:900;letter-spacing:-.09em;color:#171615;text-decoration:none}.nav-link{font-weight:800;color:#171615!important}.profile-wrap{position:relative}.profile-btn{display:flex;align-items:center;gap:.45rem;border:0;background:transparent;font-weight:800}.profile-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--o);color:#fff;font-size:1.45rem;box-shadow:0 2px 7px #ff6b0066}.profile-menu{display:none;position:absolute;right:0;top:58px;width:275px;background:#fff;border:1px solid #ddd;border-radius:10px;box-shadow:0 12px 35px #0002;padding:1rem;z-index:30}.profile-menu.open{display:block}.profile-menu a{display:block;color:#171615;text-decoration:none;padding:.45rem 0;font-size:.9rem;font-weight:600}.profile-menu a:hover{color:var(--o)}.orange{color:var(--o)}.form-control{height:52px}.search{position:relative}.search span{position:absolute;left:14px;top:10px;font-size:1.4rem;color:#888}.search input{padding-left:2.7rem}.job-list,.details{background:#fff;border:1px solid #ddd;border-radius:9px}.job-list{height:650px;overflow:auto;padding:.8rem}.card-job{width:100%;text-align:left;background:#fff;border:1px solid #ddd;border-radius:8px;padding:1.1rem;margin-bottom:.7rem}.card-job:hover,.card-job.active{border-color:var(--b);background:#f2f7ff;box-shadow:0 0 0 2px #146cff20}.card-job h3{font-size:1rem;font-weight:900;margin:.7rem 0}.details{height:650px;overflow:auto;padding:2rem}.type{color:var(--o);font-weight:800}.location{color:var(--b);font-weight:700}.save{border:1px solid #bbb;background:#fff;border-radius:7px;padding:.55rem 1rem;font-weight:800}.save.saved{color:#e02020;border-color:#e02020}.empty{padding:5rem;text-align:center;background:#fff;border-radius:9px}@media(max-width:575px){.page{padding-left:18px!important;padding-right:18px!important}.profile-label{display:none}}</style></head><body><header class="top"><div class="page container py-3 d-flex gap-4 align-items-center"><a class="brand" href="dashboard.php">VUKA</a><nav class="d-none d-md-flex gap-4"><a class="nav-link" href="dashboard.php">Home</a><a class="nav-link" href="jobs.php">Jobs</a><a class="nav-link" href="jobs.php?saved=1">Saved</a></nav><div class="ms-auto profile-wrap"><button class="profile-btn" id="profileButton" type="button"><span class="profile-label">Profile</span><span class="profile-icon">👤</span></button><div class="profile-menu" id="profileMenu"><b><?php echo htmlspecialchars($account['full_name']??'User');?></b><small class="d-block text-secondary mb-2"><?php echo htmlspecialchars($account['email']??'');?></small><span class="small fw-bold orange">0 Vuka points</span><hr class="my-2"><a href="#">My Profile</a><a href="#">Career preferences</a><a href="#">Messages</a><a href="#">Notifications</a><a href="#">Vuka points</a><a href="#">Invite friends</a><a href="#">Notification settings</a><a href="#">Account settings</a><a href="#">FAQ</a><hr class="my-2"><a class="text-danger" href="logout.php">Log out</a></div></div></div></header><section class="filters py-3"><div class="page container"><div class="row g-3"><div class="col-md-6"><div class="search"><span>⌕</span><input class="form-control" id="text" placeholder="Search jobs, company or job type"></div></div><div class="col-md-4"><div class="search"><span>⌖</span><input class="form-control" id="place" placeholder="Country, state, city or town"></div></div><div class="col-md-2"><button class="btn text-white fw-bold w-100" style="height:52px;background:var(--o)" onclick="filterJobs()">Show jobs</button></div></div></div></section><main class="page container py-4"><div class="d-flex justify-content-between mb-4"><div><h1 class="h2 fw-bold mb-1"><?php echo $savedOnly?'Saved jobs':'Find jobs';?></h1><b><span id="count"><?php echo count($jobs);?></span> jobs found</b></div><?php if($savedOnly):?><a class="btn btn-outline-secondary" href="jobs.php">Show all jobs</a><?php endif;?></div><?php if($jobs):?><div class="row g-4"><div class="col-lg-4"><div class="job-list"><?php foreach($jobs as $j):?><button class="card-job <?php echo $j['id']===$first['id']?'active':'';?>" data-id="<?php echo $j['id'];?>" data-title="<?php echo htmlspecialchars($j['title'],ENT_QUOTES);?>" data-company="<?php echo htmlspecialchars($j['company'],ENT_QUOTES);?>" data-location="<?php echo htmlspecialchars($j['location'],ENT_QUOTES);?>" data-type="<?php echo htmlspecialchars($j['job_type'],ENT_QUOTES);?>" data-description="<?php echo htmlspecialchars($j['description'],ENT_QUOTES);?>" data-date="<?php echo date('j M Y',strtotime($j['created_at']));?>" data-saved="<?php echo $j['saved_id']?1:0;?>"><b><?php echo htmlspecialchars($j['company']);?></b><h3><?php echo htmlspecialchars($j['title']);?></h3><small>⌖ <?php echo htmlspecialchars($j['location']);?></small><div class="d-flex justify-content-between mt-3"><small>Posted <?php echo date('j M Y',strtotime($j['created_at']));?></small><small><?php echo htmlspecialchars($j['job_type']);?></small></div></button><?php endforeach;?></div></div><div class="col-lg-8"><article class="details"><span class="type" id="dType"></span><p class="fw-bold mt-3 mb-1" id="dCompany"></p><h2 class="display-6 fw-bold" id="dTitle"></h2><p class="location" id="dLocation"></p><p class="text-secondary" id="dDate"></p><hr class="my-4"><button class="btn text-white fw-bold px-4" style="background:var(--o)">Apply</button> <button class="save" id="save">♡ Save</button><div class="bg-light rounded p-4 mt-4"><h3 class="h5 fw-bold">Job details</h3><div class="row"><div class="col-md-6"><b>Location</b><p class="text-secondary" id="bLocation"></p></div><div class="col-md-6"><b>Contract type</b><p class="text-secondary" id="bType"></p></div></div><hr><h3 class="h5 fw-bold">Description</h3><p class="text-secondary" id="dDescription" style="white-space:pre-line"></p></div></article></div></div><?php else:?><div class="empty"><h2 class="h4 fw-bold">No saved jobs yet</h2><p class="text-secondary">Use the save button on a job to find it here later.</p><a class="btn text-white" style="background:var(--o)" href="jobs.php">Browse all jobs</a></div><?php endif;?></main><script>profileButton.onclick=()=>profileMenu.classList.toggle('open');document.addEventListener('click',e=>{if(!e.target.closest('.profile-wrap'))profileMenu.classList.remove('open')});const cards=[...document.querySelectorAll('.card-job')],save=document.getElementById('save');let picked;function show(c){picked=c;cards.forEach(x=>x.classList.toggle('active',x===c));dType.textContent=c.dataset.type;dCompany.textContent=c.dataset.company;dTitle.textContent=c.dataset.title;dLocation.textContent='⌖ '+c.dataset.location;dDate.textContent='Posted: '+c.dataset.date;bLocation.textContent=c.dataset.location;bType.textContent=c.dataset.type;dDescription.textContent=c.dataset.description;save.dataset.id=c.dataset.id;save.classList.toggle('saved',c.dataset.saved==='1');save.textContent=c.dataset.saved==='1'?'♥ Saved':'♡ Save'}cards.forEach(c=>c.onclick=()=>show(c));if(cards.length)show(cards.find(c=>c.classList.contains('active')));function filterJobs(){let t=text.value.toLowerCase(),p=place.value.toLowerCase(),n=0;cards.forEach(c=>{let yes=(!t||[c.dataset.title,c.dataset.company,c.dataset.type].join(' ').toLowerCase().includes(t))&&(!p||c.dataset.location.toLowerCase().includes(p));c.style.display=yes?'block':'none';if(yes)n++});count.textContent=n;let first=cards.find(c=>c.style.display!=='none');if(first)show(first)}if(save)save.onclick=async()=>{let f=new FormData();f.append('job_id',save.dataset.id);let r=await fetch('save-job.php',{method:'POST',body:f});let d=await r.json();if(d.ok){picked.dataset.saved=d.saved?'1':'0';show(picked);if(location.search.includes('saved=1')&&!d.saved)picked.style.display='none'}};</script></body></html>
